{
  "title": "VPN Troubleshooting Checklist",
  "generated": "2026-02-28",
  "source_articles": ["kb_001", "kb_006", "kb_007"],
  "critical_note": "FortiClient VPN is deprecated as of March 1, 2026. All users must migrate to GlobalProtect VPN client (Palo Alto Networks). See kb_006 for migration details.",
  "prerequisites": [
    {
      "step": 1,
      "action": "Uninstall FortiClient VPN client",
      "source": "kb_006"
    },
    {
      "step": 2,
      "action": "Download GlobalProtect VPN client from https://vpn.company.com/downloads",
      "source": "kb_006"
    },
    {
      "step": 3,
      "action": "Install and launch GlobalProtect",
      "source": "kb_006"
    }
  ],
  "connection_steps": [
    {
      "step": 1,
      "action": "Click [Remote Access] in GlobalProtect",
      "source": "kb_001"
    },
    {
      "step": 2,
      "action": "Enter server address: vpn.company.com",
      "source": "kb_001"
    },
    {
      "step": 3,
      "action": "Log in with company email and password",
      "source": "kb_001"
    },
    {
      "step": 4,
      "action": "Select [Full Tunnel Mode] to connect",
      "source": "kb_001"
    }
  ],
  "troubleshooting": {
    "connection_timeout": [
      {
        "issue": "Connection timeout",
        "solution": "Check network connection and ensure firewall is not blocking VPN port 443",
        "source": "kb_001, kb_007"
      }
    ],
    "authentication_failure": [
      {
        "issue": "Authentication failure",
        "solution": "Confirm password has not expired; reset at https://password.company.com",
        "source": "kb_001"
      }
    ],
    "cannot_access_intranet": [
      {
        "issue": "Cannot access intranet after connecting",
        "solution": "Disconnect and reconnect VPN, or contact IT hotline ext.8888",
        "source": "kb_001"
      }
    ],
    "frequent_disconnections": [
      {
        "issue": "Frequent disconnections",
        "solution": "Switch to 5GHz WiFi or use a wired connection",
        "source": "kb_007"
      }
    ],
    "video_conferencing_lag": [
      {
        "issue": "Video conferencing lag",
        "solution": "Close other bandwidth-consuming applications",
        "source": "kb_007"
      }
    ]
  },
  "additional_notes": [
    {
      "note": "VPN password syncs with email password and must be changed every 90 days",
      "source": "kb_001"
    },
    {
      "note": "Special VPN permissions must be requested in advance for overseas business trips",
      "source": "kb_001"
    },
    {
      "note": "Recommended bandwidth: Download 50Mbps+ / Upload 10Mbps+",
      "source": "kb_003"
    },
    {
      "note": "For large files (>100MB), use the company FTP server instead of VPN sync",
      "source": "kb_007"
    }
  ],
  "support": {
    "it_hotline": "ext.8888",
    "password_reset": "https://password.company.com",
    "vpn_downloads": "https://vpn.company.com/downloads"
  }
}
